DROP TABLE IF EXISTS `document`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `document` (
  `id` char(36) NOT NULL COMMENT '文档 UUID',
  `kb_id` char(36) DEFAULT NULL COMMENT '所属知识库 UUID',
  `folder_id` char(36) DEFAULT NULL COMMENT '所属文件夹 UUID',
  `title` text NOT NULL COMMENT '标题',
  `doc_type` varchar(20) NOT NULL COMMENT '文档类型',
  `source_url` text COMMENT '来源网址',
  `source_path` text COMMENT '来源路径',
  `stored_path` text COMMENT '应用内文件路径',
  `raw_text` longtext NOT NULL COMMENT '规范化正文',
  `parse_status` varchar(16) NOT NULL DEFAULT 'pending' COMMENT '解析状态',
  `index_status` varchar(16) NOT NULL DEFAULT 'pending' COMMENT '索引状态',
  `promoted_from_timeline_id` char(36) DEFAULT NULL COMMENT '升格来源时间线 UUID',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '软删除时间（UTC）',
  `created_at` datetime(3) NOT NULL COMMENT '创建时间（UTC）',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间（UTC）',
  PRIMARY KEY (`id`),
  KEY `ix_document_type_updated` (`doc_type`,`updated_at` DESC),
  KEY `fk_document_folder` (`folder_id`),
  KEY `ix_document_kb_folder_updated` (`kb_id`,`folder_id`,`updated_at` DESC),
  CONSTRAINT `fk_document_folder` FOREIGN KEY (`folder_id`) REFERENCES `knowledge_folder` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_document_kb` FOREIGN KEY (`kb_id`) REFERENCES `knowledge_base` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_document_doc_type` CHECK ((`doc_type` in (_utf8mb4'webpage',_utf8mb4'pdf',_utf8mb4'docx',_utf8mb4'markdown',_utf8mb4'txt',_utf8mb4'html',_utf8mb4'note',_utf8mb4'skill',_utf8mb4'prompt',_utf8mb4'promoted'))),
  CONSTRAINT `ck_document_index_status` CHECK ((`index_status` in (_utf8mb4'pending',_utf8mb4'indexing',_utf8mb4'ready',_utf8mb4'failed',_utf8mb4'stale'))),
  CONSTRAINT `ck_document_parse_status` CHECK ((`parse_status` in (_utf8mb4'pending',_utf8mb4'ready',_utf8mb4'failed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识文档';
/*!40101 SET character_set_client = @saved_cs_client */;

